//! Whole immutable-original policy/report and finite DATA comparisons.
use crate::lint::Registry;
#[path="../fixtures/original_policies/instance_list.rs"]mod original;
#[path="../fixtures/native-instance-list/fixture.rs"]mod fixture;
fn record(outcome:&crate::run::Outcome)->serde_json::Value{serde_json::json!({"sites":outcome.run.sites,"notes":outcome.run.notes,"allow_used":outcome.allow_used,"failed":outcome.failed,"text":outcome.text})}
#[test]fn instance_list_unique_core_preserves_full_original_hidden_ntfs_singleton_allow_and_report(){for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("instance-list-original-{case}"));for(relative,bytes)in fixture::files(case).unwrap(){let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["instance_list".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options.clone()).unwrap();let current=crate::run::Engine::new(crate::run::registry(),options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let actual=current.run_one(current.reg.lints.iter().find(|lint|lint.meta().name=="instance_list").unwrap().as_ref());assert_eq!(record(&actual),record(&expected),"entire original instance-list {case}");assert!(!expected.run.sites.is_empty());println!("INSTANCE_LIST_WHOLE_ORIGINAL={}",serde_json::json!({"case":case,"record":record(&actual)}));}}
#[cfg(feature="native-policy")]struct Pages<'a>{root:&'a std::path::Path,rows:Vec<(String,dm_preprocess::SourceText)>,budget:std::sync::Arc<crate::captured_generator_budget::Budget>,config:crate::captured_raw_file::Config,passes:std::cell::Cell<usize>,stop:Option<usize>}
#[cfg(feature="native-policy")]impl crate::reactive_raw_policy_pages::RawPolicyPages for Pages<'_>{fn for_each(&self,visit:&mut dyn FnMut(&str,crate::captured_raw_file::RawPolicyViews<'_>)->Result<bool,crate::captured_reactive_reads::Failure>)->Result<bool,crate::captured_reactive_reads::Failure>{let pass=self.passes.get();self.passes.set(pass+1);for(relative,text)in &self.rows{if pass==1&&self.config.policy_path_exempt("instance_list","",relative){continue}if !crate::captured_raw_file::with_original_policy_file(self.root,&self.root.join(relative),text.clone(),0,&self.budget,visit)?{return Ok(false)}}Ok(self.stop!=Some(pass))}}
#[cfg(feature="native-policy")]#[test]fn instance_list_native_data_matches_frozen_original_without_complete_source_authority(){use crate::{captured_generator_budget::Budget,captured_raw_policy::Configuration};for case in fixture::CASES{let root=crate::test_scratch::dir(&format!("instance-list-native-{case}"));let files=fixture::files(case).unwrap();for(relative,bytes)in &files{let file=root.join(relative);std::fs::create_dir_all(file.parent().unwrap()).unwrap();std::fs::write(file,bytes).unwrap();}let options=crate::run::Options{root:root.clone(),lints:vec!["instance_list".into()],raw:true,no_cache:true,..Default::default()};let mut registry=Registry::default();original::register(&mut registry);let old=crate::run::Engine::new(registry,options).unwrap();let expected=old.run_one(old.reg.lints[0].as_ref());let budget=Budget::new(32*1024*1024).unwrap();let mut rows=Vec::new();for(relative,text)in &files{if !crate::instance_list_policy::META.select.matches_path(relative){continue}let acquired=dm_preprocess::AcquiredSource::from_original_bytes(text.clone(),());rows.push((relative.clone(),acquired.lease().source_text().clone()));}rows.sort_by(|a,b|a.0.cmp(&b.0));let config=files.iter().find(|(p,_)|p=="tools/ci/lint_scopes.toml").unwrap().1.as_slice();let mut pages=Pages{root:&root,rows,budget:budget.clone(),config:crate::captured_raw_file::Config::capture(Configuration::Captured(config)).unwrap(),passes:std::cell::Cell::new(0),stop:None};let actual=crate::captured_instance_list_pages::collect_from_pages(&pages,&budget,&||Ok(())).unwrap();assert_eq!(actual.sites(),expected.run.sites.as_slice(),"sites {case}");assert_eq!(actual.allow_used(),expected.allow_used.as_slice(),"ALLOW {case}");assert_eq!(pages.passes.get(),2);for(site,text)in actual.sites().iter().zip(actual.source_text()){assert_eq!(*text,old.tree.site_text(&site.rel,site.line as usize));}for used in actual.allow_used(){assert_eq!(actual.allow_digests().get(&used.rel),Some(&crate::captured_raw_file::source_allow_digest(old.tree.get(&used.rel).unwrap())));}pages.passes.set(0);pages.stop=Some(1);let fresh=Budget::new(32*1024*1024).unwrap();assert!(crate::captured_instance_list_pages::collect_from_pages(&pages,&fresh,&||Ok(())).is_err());}}
